 export const TASA_IVA = 0.13;

+// Tasa de IVA configurable por entorno (variable TASA_IVA, número entre 0 y 1). Sin definir, 0.13.
+// Un valor inválido es un error: no se factura con una tasa que no se entiende.
+export function tasaIva(env = process.env) {
+  const crudo = env.TASA_IVA;
+  if (crudo === undefined) return TASA_IVA;
+  if (!/^(?:\d+\.?\d*|\.\d+)$/.test(crudo)) throw new Error(`TASA_IVA inválida: "${crudo}"`);
+  const tasa = Number(crudo);
+  if (tasa < 0 || tasa > 1) throw new RangeError(`TASA_IVA fuera de rango 0–1: "${crudo}"`);
+  return tasa;
+}
